/* ==========================================================================
   I18N.JS — translations: English, French, Arabic (Arabic pages are right-to-left)

   How it works
     - Each line is   "key": ["English", "Français", "العربية"]
     - In HTML:  <span data-i18n="nav.jobs"></span>        → text
                 <h2 data-i18n-html="home.companiesTitle">  → text with <span> styling
                 <input data-i18n-ph="home.searchPh">        → placeholder
     - In JS:    t("jobs.found", { n: 12 })   → "12 offers found"
   To add a language, add a 4th column and a code in LANG_NAMES.
   ========================================================================== */
const LANG_NAMES = { en: "English", fr: "Français", ar: "العربية" };
const LANG = (() => {
  let saved = null;
  try { saved = localStorage.getItem("jf_lang"); } catch (_) {}
  const browser = (navigator.language || "en").slice(0, 2);
  return LANG_NAMES[saved] ? saved : LANG_NAMES[browser] ? browser : "en";
})();
const DIR = LANG === "ar" ? "rtl" : "ltr";
const LOCALE = { en: "en-GB", fr: "fr-FR", ar: "ar-MA" }[LANG];
document.documentElement.lang = LANG;
document.documentElement.dir = DIR;

